INSERT INTO involucrado_hecho (id_hecho, id_involucrado, id_tipo_involucramiento) SELECT (SELECT h.id_hecho FROM hecho h  WHERE h.id_ubicacion = p.id_origen    AND h.fecha_hecho = '2023-11-26'  ORDER BY h.id_hecho DESC ROWS 1), p.id_persona, COALESCE((SELECT id_involucramiento FROM involucramiento WHERE UPPER(TRIM(nombre)) = UPPER('Agraviado') ROWS 1),          (SELECT id_involucramiento FROM involucramiento WHERE UPPER(TRIM(nombre)) = UPPER('Victimario') ROWS 1)) FROM persona p WHERE p.nombres = 'AGR_2023_392521' AND p.apellidos = 'AGRAVIADOS' AND NOT EXISTS (SELECT 1 FROM involucrado_hecho ih WHERE ih.id_involucrado = p.id_persona   AND ih.id_hecho = (SELECT h.id_hecho FROM hecho h  WHERE h.id_ubicacion = p.id_origen    AND h.fecha_hecho = '2023-11-26'  ORDER BY h.id_hecho DESC ROWS 1));
